import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";import"./chunks/assets.DfIShTN7.js";var i=JSON.parse(`{"title":"Hermes Agent — Mi propia infraestructura","description":"Hermes Agent: cerebro de IA autoalojado (hermes-stack) que enruta modelos, corre automatizaciones y mantiene abastecida a mi flota de agentes.","frontmatter":{"title":"Hermes Agent — Mi propia infraestructura","description":"Hermes Agent: cerebro de IA autoalojado (hermes-stack) que enruta modelos, corre automatizaciones y mantiene abastecida a mi flota de agentes."},"headers":[],"relativePath":"es/agentic/hermes/index.md","filePath":"es/agentic/hermes/index.md"}`),a={name:`es/agentic/hermes/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="hermes-agent-—-mi-propia-infraestructura" tabindex="-1">Hermes Agent — Mi propia infraestructura <a class="header-anchor" href="#hermes-agent-—-mi-propia-infraestructura" aria-label="Permalink to “Hermes Agent — Mi propia infraestructura”">​</a></h1><p><strong>Hermes Agent</strong> es la pieza que construí yo mismo: la capa coordinadora de todo mi montaje agéntico, publicada como <a href="https://github.com/Godde3s/hermes-stack" target="_blank" rel="noreferrer">hermes-stack</a> en un Hugging Face Space gratuito. Las otras herramientas son individuos; Hermes es el <em>gerente</em> — enruta modelos, guarda contexto, corre automatizaciones y mantiene a cada agente abastecido con el cerebro correcto a la hora correcta.</p><h2 id="lo-que-hermes-realmente-hace-todo-el-dia" tabindex="-1">Lo que Hermes realmente hace todo el día <a class="header-anchor" href="#lo-que-hermes-realmente-hace-todo-el-dia" aria-label="Permalink to “Lo que Hermes realmente hace todo el día”">​</a></h2><ul><li><strong>Enrutamiento de modelos.</strong> Cada petición de cada herramienta puede fluir por mi <a href="/Usf/es/projects/omnirouter/">OmniRouter</a> — modelos baratos para el trabajo sucio, premium para los juicios difíciles.</li><li><strong>Cerebro de automatización.</strong> Tareas activadas por webhook: vigilar un repo, avisarme por Telegram cuando un despliegue se rompe, resumir logs nocturnos de CI.</li><li><strong>Guardián de contexto.</strong> Los proyectos largos guardan sus briefs, decisiones y estado con Hermes, no regados en scrolls de terminales.</li><li><strong>Endpoint itinerante.</strong> Cualquier cliente compatible con OpenAI puede hablarle — la app del teléfono, un cron job, otro agente.</li></ul><h2 id="¿por-que-autoalojarlo" tabindex="-1">¿Por qué autoalojarlo? <a class="header-anchor" href="#¿por-que-autoalojarlo" aria-label="Permalink to “¿Por qué autoalojarlo?”">​</a></h2><p>Porque la dependencia es una decisión de diseño. Un &quot;asistente de IA&quot; alojado puede cambiar precios, limitarte por tasa o desaparecer — y en mi región también puede bloquearse por completo. Hermes Stack corre en infraestructura que controlo, detrás de routers que controlo, con fallbacks que configuré yo. Cuando un proveedor muere, nada cambia en mi flujo; el router simplemente deja de preguntarle.</p><figure class="concept-illustration"><img src="/Usf/assets/img/agentic-loop.svg" alt="Hermes coordinando OpenCode, Codex y Claude Code" loading="lazy"><figcaption>Un cerebro, tres especialistas, cero vendor lock-in.</figcaption></figure><div class="tip custom-block"><p class="custom-block-title">Despliega el tuyo</p><p>Todo el stack está a un clic del repo: <a href="https://github.com/Godde3s/hermes-stack" target="_blank" rel="noreferrer">github.com/Godde3s/hermes-stack</a> — amigable con el tier gratuito, documentado, y mío por derecho a mejorarlo en público.</p></div>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};